(function() {
    'use strict';

    class GeoriskAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Geopolitical Risk Navigator';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    title: 'Semiconductor Sovereignty',
                    briefing: '<b>US BIS Restriction:</b> KorTech Ltd. (Taiwan), your critical IGBT module supplier, has been added to the Entity List under US Export Administration Regulations. Component qualification for alternatives takes 9 months. Your industrial motor control products depend on these modules across all manufacturing sites.<br><br><b>Secondary signal:</b> Colombian political transition announced. The incoming government platform emphasizes economic sovereignty and local content policies.',
                    decA: {
                        label: 'Sourcing Strategy',
                        options: [
                            { text: 'Qualify European alternative (Infineon, 9 months, $2.1M)', scores: [5, 9, 8, 7, 9] },
                            { text: 'Negotiate BIS license exception (uncertain, 6-12 months)', scores: [7, 4, 5, 5, 4] },
                            { text: 'Build 12-month strategic inventory buffer', scores: [8, 6, 3, 4, 3] },
                            { text: 'Source from Chinese manufacturer (new USMCA risk)', scores: [6, 5, 2, 3, 5] }
                        ]
                    },
                    decB: {
                        label: 'Organizational Response',
                        options: [
                            { text: 'Create internal Export Controls Office', scores: [6, 7, 8, 8, 9] },
                            { text: 'Retain Washington DC trade law firm', scores: [5, 4, 6, 5, 5] },
                            { text: 'Engage US Chamber of Commerce advocacy', scores: [7, 5, 7, 7, 6] }
                        ]
                    },
                    decC: {
                        label: 'Supply Chain Redesign',
                        options: [
                            { text: 'Map all products for EAR and US-origin exposure', scores: [5, 9, 9, 8, 9] },
                            { text: 'Dual-source top 10 China-origin components', scores: [7, 7, 6, 6, 7] },
                            { text: 'Build geopolitical risk register for procurement', scores: [6, 6, 8, 8, 8] }
                        ]
                    }
                },
                {
                    title: 'Local Content Nationalism',
                    briefing: '<b>Colombia Decreto 847:</b> The new government requires industrial manufacturers to source 35% of input materials locally within 24 months, or face 12% tariff surcharges on imported components.<br><br>Your Medellin plant employs 1,200 people and currently sources 71% of components internationally. Colombian suppliers exist for basic assemblies but not precision electronics.<br><br>The decreto includes a Sectoral Exception clause for industries lacking domestic production capacity.',
                    decA: {
                        label: 'Compliance Strategy',
                        options: [
                            { text: 'Full compliance: develop Colombian supplier ecosystem ($3.8M)', scores: [4, 7, 9, 9, 8] },
                            { text: 'Partial compliance: substitute easy components only', scores: [7, 5, 5, 5, 4] },
                            { text: 'Apply for Sectoral Exception (uncertain outcome)', scores: [6, 4, 6, 6, 5] }
                        ]
                    },
                    decB: {
                        label: 'Government Negotiation',
                        options: [
                            { text: 'Offer $5M voluntary investment for compliance extension', scores: [5, 6, 8, 9, 7] },
                            { text: 'Engage industry chamber for collective negotiation', scores: [7, 5, 7, 7, 6] },
                            { text: 'Present technical analysis to Ministry of Commerce', scores: [6, 5, 8, 8, 8] }
                        ]
                    },
                    decC: {
                        label: 'Operational Decision',
                        options: [
                            { text: 'Transfer production to Mexico (lose 1,200 jobs)', scores: [8, 4, 3, 2, 5] },
                            { text: 'Maintain Colombia as primary base, absorb costs', scores: [4, 6, 7, 8, 6] },
                            { text: 'Bifurcate: high-tech to Mexico, assemblies in Colombia', scores: [6, 7, 6, 7, 8] }
                        ]
                    }
                },
                {
                    title: 'Border Dispute and Capital Controls',
                    briefing: '<b>Military escalation:</b> The Colombia-Venezuela border dispute has escalated. Both countries close the border for overland transit. Your Medellin-to-Caracas supply route is severed and port access is disrupted by military checkpoints.<br><br><b>Simultaneous crisis:</b> Argentina announces foreign exchange regulations restricting profit repatriation for companies above ARS 10 billion. Your Buenos Aires subsidiary is affected.<br><br>Two crises demand response with limited budget and management bandwidth.',
                    decA: {
                        label: 'Logistics Rerouting',
                        options: [
                            { text: 'Air freight Medellin to Caracas (7x cost, reliable)', scores: [4, 8, 5, 6, 5] },
                            { text: 'Reroute via Ecuador (18-day delay, 2.3x cost)', scores: [6, 6, 6, 6, 6] },
                            { text: 'Activate contingency stock at Caracas distributor', scores: [8, 9, 7, 7, 8] },
                            { text: 'Suspend Venezuela sales, redeploy inventory', scores: [7, 3, 4, 4, 4] }
                        ]
                    },
                    decB: {
                        label: 'Intelligence and Early Warning',
                        options: [
                            { text: 'Subscribe to OSINT political risk monitoring service', scores: [6, 7, 8, 7, 8] },
                            { text: 'Establish formal Country Risk Committee (quarterly)', scores: [5, 6, 8, 8, 9] },
                            { text: 'Build Early Warning Indicator dashboard for top 5 risks', scores: [6, 8, 8, 7, 9] }
                        ]
                    },
                    decC: {
                        label: 'Argentina Transfer Restriction',
                        options: [
                            { text: 'Retain profits in ARS, invest in local assets as hedge', scores: [5, 5, 6, 5, 5] },
                            { text: 'Engage Central Bank for repatriation approval', scores: [6, 5, 7, 7, 6] },
                            { text: 'Structure intercompany loans to replace dividends', scores: [8, 5, 5, 4, 6] },
                            { text: 'Reduce Argentina to asset-light model', scores: [7, 4, 4, 3, 7] }
                        ]
                    }
                },
                {
                    title: 'ESG Divestment Campaign',
                    briefing: '<b>Investor pressure:</b> European institutional investors holding 18% of equity label your company a governance-risk holding due to Colombia and Argentina operations. You have 90 days to present a credible risk management framework or face coordinated divestment.<br><br>A proxy advisory firm has placed an ESG resolution on the annual general meeting agenda. Stock price is at risk.<br><br>Your earlier operational decisions now become your investor narrative. Strong prior risk management makes this challenge manageable.',
                    decA: {
                        label: 'Investor Relations Response',
                        options: [
                            { text: 'Prepare comprehensive Geopolitical Risk Management Report', scores: [6, 7, 8, 9, 9] },
                            { text: 'Request bilateral meetings with top 3 shareholders', scores: [7, 5, 6, 8, 6] },
                            { text: 'Commission independent third-party political risk audit', scores: [5, 6, 8, 9, 8] }
                        ]
                    },
                    decB: {
                        label: 'Governance Response',
                        options: [
                            { text: 'Establish Board-Level Geopolitical Risk Committee', scores: [5, 7, 8, 9, 9] },
                            { text: 'Disclose Risk Appetite Statement in quarterly filing', scores: [6, 6, 7, 8, 8] },
                            { text: 'Publish country-level risk assessments annually', scores: [6, 6, 8, 8, 7] }
                        ]
                    },
                    decC: {
                        label: 'Strategic Response',
                        options: [
                            { text: 'Divest Argentina subsidiary to demonstrate discipline', scores: [7, 4, 5, 6, 4] },
                            { text: 'Announce country exposure cap policy (max 25%)', scores: [6, 6, 7, 8, 8] },
                            { text: 'Rebalance portfolio toward USMCA-integrated operations', scores: [8, 5, 5, 5, 6] }
                        ]
                    }
                },
                {
                    title: 'Regional Free Trade Agreement',
                    briefing: '<b>Positive shock:</b> After 18 years of negotiation, the MERCOSUR-EU Free Trade Agreement is ratified. Tariffs on industrial equipment from Brazil to the EU drop from 7-12% to 0-2% over five years.<br><br>Companies that maintained LATAM manufacturing capacity are positioned to capture this opportunity. Those that over-retreated in previous rounds face structural disadvantage.<br><br>Simultaneously, European industrial competitors gain improved access to Brazilian and Argentine markets.',
                    decA: {
                        label: 'Brazil Opportunity',
                        options: [
                            { text: 'Restructure Brazil plant as MERCOSUR export base for EU', scores: [8, 7, 7, 7, 9] },
                            { text: 'Joint venture with European industrial partner', scores: [7, 6, 7, 8, 8] },
                            { text: 'Extract tariff reduction as margin improvement only', scores: [9, 5, 5, 5, 4] }
                        ]
                    },
                    decB: {
                        label: 'Argentina Re-evaluation',
                        options: [
                            { text: 'Reverse divestment plans, reinvest in Argentina operations', scores: [6, 6, 7, 7, 8] },
                            { text: 'Maintain current Argentina position unchanged', scores: [7, 6, 6, 6, 6] },
                            { text: 'Continue planned exit regardless of FTA opportunity', scores: [5, 4, 4, 4, 3] }
                        ]
                    },
                    decC: {
                        label: 'Portfolio Rebalancing',
                        options: [
                            { text: 'Shift manufacturing network toward MERCOSUR markets', scores: [7, 7, 7, 7, 9] },
                            { text: 'Maintain balanced portfolio across all regions', scores: [7, 7, 7, 7, 7] },
                            { text: 'Double down on USMCA, treat FTA as secondary', scores: [8, 5, 5, 5, 4] }
                        ]
                    }
                },
                {
                    title: 'Board Presentation: Strategic Synthesis',
                    briefing: '<b>Final round:</b> Present your geopolitical risk assessment and strategic recommendations to the Board of Directors. Your presentation must demonstrate mastery of the frameworks applied throughout the simulation.<br><br>The Board evaluates: structural completeness, quantitative rigor, prioritization logic, and actionability of recommendations.<br><br>This is not a game round but a real deliverable. The quality of your risk communication framework determines your final Strategic Adaptation score.',
                    decA: {
                        label: 'Risk Communication Framework',
                        options: [
                            { text: 'Full quantitative risk matrix with scenario-based P&L', scores: [6, 7, 8, 9, 9] },
                            { text: 'Qualitative narrative with country risk summaries', scores: [5, 4, 5, 6, 4] },
                            { text: 'Mixed approach: key metrics integrated with narrative', scores: [7, 6, 7, 8, 8] }
                        ]
                    },
                    decB: {
                        label: 'Strategic Recommendation Focus',
                        options: [
                            { text: 'Prioritize supply chain resilience investment', scores: [6, 9, 7, 7, 8] },
                            { text: 'Prioritize government relations expansion across LATAM', scores: [6, 6, 9, 9, 7] },
                            { text: 'Prioritize geographic portfolio rebalancing', scores: [8, 6, 6, 6, 8] }
                        ]
                    },
                    decC: {
                        label: 'Monitoring Framework',
                        options: [
                            { text: 'Leading indicators dashboard with quarterly Board review', scores: [6, 8, 8, 9, 9] },
                            { text: 'Annual risk assessment with external audit cycle', scores: [6, 6, 7, 8, 7] },
                            { text: 'Real-time OSINT monitoring with automated alert system', scores: [5, 8, 8, 7, 8] }
                        ]
                    }
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    bizPerf: 0,
                    scResil: 0,
                    polRisk: 0,
                    stkTrust: 0,
                    stratAdapt: 0,
                    totalScore: 0,
                    bizPerfHistory: [],
                    scResilHistory: [],
                    polRiskHistory: [],
                    stkTrustHistory: [],
                    stratAdaptHistory: [],
                    totalScoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decA: 1,
                    decB: 1,
                    decC: 1
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            // FIX(v1.1.0): do NOT rebuild the selects here. _rebuildSelect()
            // resets each <select> to its first option, so reading the values
            // immediately afterwards discarded the learner's choices (every
            // decision was recorded as option 1). Just read the live values.
            var selA = document.getElementById('decAInput');
            var selB = document.getElementById('decBInput');
            var selC = document.getElementById('decCInput');

            if (selA) decisions.decA = parseInt(selA.value);
            if (selB) decisions.decB = parseInt(selB.value);
            if (selC) decisions.decC = parseInt(selC.value);

            if (!decisions.decA || !decisions.decB || !decisions.decC) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('select_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var scoresA = round.decA.options[d.decA - 1].scores;
            var scoresB = round.decB.options[d.decB - 1].scores;
            var scoresC = round.decC.options[d.decC - 1].scores;

            var bizPerf = scoresA[0] + scoresB[0] + scoresC[0];
            var scResil = scoresA[1] + scoresB[1] + scoresC[1];
            var polRisk = scoresA[2] + scoresB[2] + scoresC[2];
            var stkTrust = scoresA[3] + scoresB[3] + scoresC[3];
            var stratAdapt = scoresA[4] + scoresB[4] + scoresC[4];

            var weighted = Math.round(
                bizPerf * 0.25 + scResil * 0.20 + polRisk * 0.20 +
                stkTrust * 0.20 + stratAdapt * 0.15
            );

            state.domainState.bizPerf += bizPerf;
            state.domainState.scResil += scResil;
            state.domainState.polRisk += polRisk;
            state.domainState.stkTrust += stkTrust;
            state.domainState.stratAdapt += stratAdapt;
            state.domainState.totalScore += weighted;

            state.domainState.bizPerfHistory.push(bizPerf);
            state.domainState.scResilHistory.push(scResil);
            state.domainState.polRiskHistory.push(polRisk);
            state.domainState.stkTrustHistory.push(stkTrust);
            state.domainState.stratAdaptHistory.push(stratAdapt);
            state.domainState.totalScoreHistory.push(weighted);

            // FIX(v1.1.0): advance the briefing + decision menus synchronously
            // to the next round. The previous setTimeout closure read
            // state.currentPeriod AFTER the framework had incremented it, so it
            // jumped an extra round and desynced the shown scenario from the
            // scoring table. Guard on identity so the framework's deep-cloned
            // competition preview never mutates the live DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
            }

            return {
                period: state.currentPeriod,
                roundTitle: round.title,
                bizPerf: bizPerf,
                scResil: scResil,
                polRisk: polRisk,
                stkTrust: stkTrust,
                stratAdapt: stratAdapt,
                weighted: weighted,
                cumBizPerf: state.domainState.bizPerf,
                cumScResil: state.domainState.scResil,
                cumPolRisk: state.domainState.polRisk,
                cumStkTrust: state.domainState.stkTrust,
                cumStratAdapt: state.domainState.stratAdapt,
                cumTotal: state.domainState.totalScore
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('bizPerfDisplay', 'domainState.bizPerf');
            uiManager.bind('scResilDisplay', 'domainState.scResil');
            uiManager.bind('polRiskDisplay', 'domainState.polRisk');
            uiManager.bind('stkTrustDisplay', 'domainState.stkTrust');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore');

            // FIX(v1.1.0): the framework's undo restores domainState/decisions
            // but does not re-invoke the adapter view, leaving a stale briefing
            // and decision menus. Re-render on the framework's period:undone
            // event so the scenario always matches the reverted round.
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._undoBound) {
                this._undoBound = true;
                sim.eventBus.on('period:undone', function(st) {
                    self._updateBriefing(st || sim.state);
                });
            }
        }

        getChartConfig() {
            return {
                dimensionChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Business Performance (25%)',
                                data: [],
                                borderColor: '#4caf50',
                                backgroundColor: 'rgba(76,175,80,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Supply Chain Resilience (20%)',
                                data: [],
                                borderColor: '#2196f3',
                                backgroundColor: 'rgba(33,150,243,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Risk Mitigation (20%)',
                                data: [],
                                borderColor: '#ff9800',
                                backgroundColor: 'rgba(255,152,0,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Stakeholder Trust (20%)',
                                data: [],
                                borderColor: '#9c27b0',
                                backgroundColor: 'rgba(156,39,176,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            },
                            {
                                label: 'Strategic Adaptation (15%)',
                                data: [],
                                borderColor: '#e94560',
                                backgroundColor: 'rgba(233,69,96,0.1)',
                                borderWidth: 2,
                                fill: false,
                                tension: 0.2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Performance by Dimension per Round', color: '#ccc' },
                            legend: { labels: { color: '#aaa', font: { size: 11 } } }
                        },
                        scales: {
                            y: {
                                beginAtZero: true,
                                max: 30,
                                ticks: { color: '#888' },
                                grid: { color: 'rgba(255,255,255,0.05)' }
                            },
                            x: {
                                ticks: { color: '#888' },
                                grid: { color: 'rgba(255,255,255,0.05)' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.bizPerfHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                dimensionChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.bizPerfHistory },
                        { data: state.domainState.scResilHistory },
                        { data: state.domainState.polRiskHistory },
                        { data: state.domainState.stkTrustHistory },
                        { data: state.domainState.stratAdaptHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalWeighted = history.reduce(function(s, r) { return s + (r.results ? r.results.weighted : 0); }, 0);
            var avgWeighted = Math.round(totalWeighted / history.length);
            var maxPossible = 6 * 24;

            var performance = 'Developing Strategist';
            if (totalWeighted > maxPossible * 0.8) performance = 'Expert Risk Navigator';
            else if (totalWeighted > maxPossible * 0.65) performance = 'Proficient Strategist';
            else if (totalWeighted > maxPossible * 0.5) performance = 'Competent Analyst';

            var insights = [];
            var totalBiz = history.reduce(function(s, r) { return s + (r.results ? r.results.bizPerf : 0); }, 0);
            var totalSC = history.reduce(function(s, r) { return s + (r.results ? r.results.scResil : 0); }, 0);
            var totalPol = history.reduce(function(s, r) { return s + (r.results ? r.results.polRisk : 0); }, 0);
            var totalStk = history.reduce(function(s, r) { return s + (r.results ? r.results.stkTrust : 0); }, 0);
            var totalStr = history.reduce(function(s, r) { return s + (r.results ? r.results.stratAdapt : 0); }, 0);

            var maxDim = Math.max(totalBiz, totalSC, totalPol, totalStk, totalStr);
            var minDim = Math.min(totalBiz, totalSC, totalPol, totalStk, totalStr);

            if (maxDim === totalSC) insights.push('Strongest dimension: Supply Chain Resilience. Your sourcing and logistics decisions demonstrated sophisticated risk management.');
            if (maxDim === totalPol) insights.push('Strongest dimension: Risk Mitigation. Your political risk and government relations strategies were well-calibrated.');
            if (maxDim === totalStk) insights.push('Strongest dimension: Stakeholder Trust. Your investor and government engagement built strong credibility.');
            if (maxDim === totalBiz) insights.push('Strongest dimension: Business Performance. You maintained financial discipline throughout the crises.');
            if (maxDim === totalStr) insights.push('Strongest dimension: Strategic Adaptation. Your long-term frameworks and governance architecture were comprehensive.');

            if (minDim === totalBiz) insights.push('Area for improvement: Business Performance. Consider balancing resilience investment with financial sustainability.');
            if (minDim === totalSC) insights.push('Area for improvement: Supply Chain Resilience. More proactive dual-sourcing and inventory buffers would help.');
            if (minDim === totalPol) insights.push('Area for improvement: Risk Mitigation. Proactive government relations and scenario planning can reduce political exposure.');

            return {
                totalScore: totalWeighted,
                averageRound: avgWeighted,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.weighted < 16) return window.mySimulation.t('hint_low_score');
            if (results.bizPerf <= 14 && results.stkTrust >= 20) return window.mySimulation.t('hint_biz_weak');
            if (results.stkTrust <= 14) return window.mySimulation.t('hint_trust_weak');
            if (results.scResil <= 14) return window.mySimulation.t('hint_sc_weak');
            if (results.weighted >= 22) return window.mySimulation.t('hint_strong');
            return null;
        }

